    destination_ref                 varchar(500) NOT NULL UNIQUE,
    tenant_id                       varchar(128) NOT NULL,
    system_actor_id                 varchar(160) NOT NULL,
    system_actor_type               varchar(20) NOT NULL DEFAULT 'SYSTEM' CHECK (system_actor_type = 'SYSTEM'),
    status                          varchar(20) NOT NULL DEFAULT 'ACTIVE'
                                      CHECK (status IN ('ACTIVE','INACTIVE')),
    created_at_utc                  timestamptz NOT NULL,
    updated_at_utc                  timestamptz NOT NULL,
    FOREIGN KEY (tenant_id) REFERENCES docintel.tenant_settings(tenant_id),
    FOREIGN KEY (tenant_id, system_actor_id, system_actor_type) REFERENCES docintel.actors(tenant_id, actor_id, actor_type)
);

CREATE TABLE docintel.integration_intake_events (
    tenant_id                       varchar(128) NOT NULL,
    intake_event_id                 uuid NOT NULL,
    correlation_id                  varchar(128) NOT NULL,
    source_channel                  varchar(20) NOT NULL CHECK (source_channel = 'WHATSAPP'),
    source_event_id                 varchar(300) NOT NULL,
    source_sender_ref               varchar(500),
    source_destination_ref          varchar(500),
    source_media_ref                varchar(500),
    source_event_at                 timestamptz,
    message_text                    text,
    document_id                     uuid,
    status                          varchar(20) NOT NULL
                                      CHECK (status IN ('RECEIVED','DOCUMENT_CREATED','DUPLICATE','FAILED')),
    received_at_utc                 timestamptz NOT NULL,
    PRIMARY KEY (tenant_id, intake_event_id),
    UNIQUE (tenant_id, source_event_id),
    FOREIGN KEY (tenant_id) REFERENCES docintel.tenant_settings(tenant_id),
    FOREIGN KEY (tenant_id, document_id) REFERENCES docintel.documents(tenant_id, document_id)
);

-- System-level quarantine exists because Tenant is not yet known; it is not exposed through tenant RLS APIs.
CREATE TABLE docintel.system_intake_quarantine (
    quarantine_id                   uuid PRIMARY KEY,
    correlation_id                  varchar(128) NOT NULL,
    source_channel                  varchar(20) NOT NULL CHECK (source_channel = 'WHATSAPP'),
    source_event_id                 varchar(300) NOT NULL UNIQUE,
    source_sender_ref               varchar(500),
    source_destination_ref          varchar(500),
    source_media_ref                varchar(500),
    source_event_at                 timestamptz,
    temporary_storage_id            uuid,
    temporary_logical_object_key    varchar(1000),
    file_size_bytes                 bigint CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
    content_hash_sha256             char(64),
    reason_code                     varchar(120) NOT NULL,
    status                          varchar(20) NOT NULL DEFAULT 'OPEN'
                                      CHECK (status IN ('OPEN','RESOLVED','DISCARDED')),
    received_at_utc                 timestamptz NOT NULL,
    resolved_at_utc                 timestamptz
);

-- -----------------------------------------------------------------------------
-- Idempotency
-- -----------------------------------------------------------------------------
CREATE TABLE docintel.idempotency_records (
    tenant_id                       varchar(128) NOT NULL,
    idempotency_record_id           uuid NOT NULL,
    actor_id                        varchar(160) NOT NULL,
    operation_key                   varchar(160) NOT NULL,
    idempotency_key                 varchar(240) NOT NULL,
    request_hash                    char(64) NOT NULL,
    response_status                 integer,
    response_body                   jsonb,
    created_at_utc                  timestamptz NOT NULL,
    expires_at_utc                  timestamptz NOT NULL,
    PRIMARY KEY (tenant_id, idempotency_record_id),
    UNIQUE (tenant_id, actor_id, operation_key, idempotency_key),
    FOREIGN KEY (tenant_id, actor_id) REFERENCES docintel.actors(tenant_id, actor_id)
