INSERT INTO docintel.system_audit_chain_head(singleton_key) VALUES (true) ON CONFLICT DO NOTHING;

CREATE TABLE docintel.system_audit_events (
    system_audit_event_id           uuid PRIMARY KEY,
    actor_type                      varchar(20) NOT NULL
                                      CHECK (actor_type IN ('SYSTEM','SERVICE','USER')),
    actor_id                        varchar(160) NOT NULL,
    event_type                      varchar(160) NOT NULL,
    entity_type                     varchar(80) NOT NULL,
    entity_id                       varchar(240) NOT NULL,
    occurred_at_utc                 timestamptz NOT NULL,
    correlation_id                  varchar(128),
    before_state                    jsonb,
    after_state                     jsonb,
    metadata                        jsonb,
    previous_event_hash             char(64),
    event_hash                      char(64) NOT NULL UNIQUE
);

CREATE TABLE docintel.audit_events (
    tenant_id                       varchar(128) NOT NULL,
    audit_event_id                  uuid NOT NULL,
    actor_type                      varchar(20) NOT NULL
                                      CHECK (actor_type IN ('USER','SYSTEM','SERVICE')),
    actor_id                        varchar(160) NOT NULL,
    event_type                      varchar(160) NOT NULL,
    entity_type                     varchar(80) NOT NULL,
    entity_id                       varchar(240) NOT NULL,
    occurred_at_utc                 timestamptz NOT NULL,
    correlation_id                  varchar(128),
    before_state                    jsonb,
    after_state                     jsonb,
    metadata                        jsonb,
    previous_event_hash             char(64),
    event_hash                      char(64) NOT NULL,
    PRIMARY KEY (tenant_id, audit_event_id),
    UNIQUE (tenant_id, event_hash),
    FOREIGN KEY (tenant_id, actor_id) REFERENCES docintel.actors(tenant_id, actor_id)
);

CREATE INDEX ix_audit_entity
ON docintel.audit_events(tenant_id, entity_type, entity_id, occurred_at_utc DESC);

-- -----------------------------------------------------------------------------
-- Immutability controls
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION docintel.reject_update_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'immutable row: % mutation is not allowed on %.%', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME;
END;
$$;

CREATE TRIGGER audit_events_immutable
BEFORE UPDATE OR DELETE ON docintel.audit_events
FOR EACH ROW EXECUTE FUNCTION docintel.reject_update_delete();

CREATE TRIGGER system_audit_events_immutable
BEFORE UPDATE OR DELETE ON docintel.system_audit_events
FOR EACH ROW EXECUTE FUNCTION docintel.reject_update_delete();

CREATE OR REPLACE FUNCTION docintel.guard_extraction_profile_header()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'published/retired extraction profile cannot be deleted';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status = 'RETIRED' THEN
        RAISE EXCEPTION 'retired extraction profile is immutable';
    END IF;
    IF OLD.status = 'PUBLISHED' THEN
        IF NEW.status <> 'RETIRED'
           OR NEW.profile_id IS DISTINCT FROM OLD.profile_id
           OR NEW.document_type_id IS DISTINCT FROM OLD.document_type_id
           OR NEW.scope_tenant_id IS DISTINCT FROM OLD.scope_tenant_id
           OR NEW.version_no IS DISTINCT FROM OLD.version_no
           OR NEW.profile_name IS DISTINCT FROM OLD.profile_name
           OR NEW.classification_hint IS DISTINCT FROM OLD.classification_hint
           OR NEW.created_by_actor_id IS DISTINCT FROM OLD.created_by_actor_id
           OR NEW.published_by_actor_id IS DISTINCT FROM OLD.published_by_actor_id
           OR NEW.created_at_utc IS DISTINCT FROM OLD.created_at_utc
           OR NEW.published_at_utc IS DISTINCT FROM OLD.published_at_utc
        THEN
            RAISE EXCEPTION 'published extraction profile content is immutable; only retirement during atomic supersession is allowed';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER extraction_profile_header_guard
BEFORE UPDATE OR DELETE ON docintel.extraction_profiles
FOR EACH ROW EXECUTE FUNCTION docintel.guard_extraction_profile_header();

CREATE OR REPLACE FUNCTION docintel.guard_extraction_profile_child()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    p_id uuid;
    p_status varchar(20);
BEGIN
    IF TG_TABLE_NAME = 'extraction_profile_fields' THEN
        p_id := COALESCE(NEW.profile_id, OLD.profile_id);
    ELSE
        SELECT profile_id INTO p_id
        FROM docintel.extraction_profile_fields
        WHERE profile_field_id = COALESCE(NEW.profile_field_id, OLD.profile_field_id);
    END IF;
    SELECT status INTO p_status FROM docintel.extraction_profiles WHERE profile_id = p_id;
    IF p_status IS DISTINCT FROM 'DRAFT' THEN
        RAISE EXCEPTION 'published/retired extraction profile children are immutable';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER extraction_profile_fields_guard
BEFORE INSERT OR UPDATE OR DELETE ON docintel.extraction_profile_fields
FOR EACH ROW EXECUTE FUNCTION docintel.guard_extraction_profile_child();
CREATE TRIGGER profile_field_normalizers_guard
BEFORE INSERT OR UPDATE OR DELETE ON docintel.profile_field_normalizers
FOR EACH ROW EXECUTE FUNCTION docintel.guard_extraction_profile_child();
CREATE TRIGGER profile_field_validators_guard
BEFORE INSERT OR UPDATE OR DELETE ON docintel.profile_field_validators
FOR EACH ROW EXECUTE FUNCTION docintel.guard_extraction_profile_child();

CREATE OR REPLACE FUNCTION docintel.guard_requirement_profile_header()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'published/retired requirement profile cannot be deleted';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status = 'RETIRED' THEN
        RAISE EXCEPTION 'retired requirement profile is immutable';
    END IF;
    IF OLD.status = 'PUBLISHED' THEN
        IF NEW.status <> 'RETIRED'
           OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
           OR NEW.requirement_profile_id IS DISTINCT FROM OLD.requirement_profile_id
           OR NEW.profile_key IS DISTINCT FROM OLD.profile_key
           OR NEW.version_no IS DISTINCT FROM OLD.version_no
           OR NEW.description IS DISTINCT FROM OLD.description
           OR NEW.created_by_actor_id IS DISTINCT FROM OLD.created_by_actor_id
           OR NEW.published_by_actor_id IS DISTINCT FROM OLD.published_by_actor_id
           OR NEW.created_at_utc IS DISTINCT FROM OLD.created_at_utc
           OR NEW.published_at_utc IS DISTINCT FROM OLD.published_at_utc
        THEN
            RAISE EXCEPTION 'published requirement profile content is immutable; only retirement during atomic supersession is allowed';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER requirement_profile_header_guard
BEFORE UPDATE OR DELETE ON docintel.document_requirement_profiles
FOR EACH ROW EXECUTE FUNCTION docintel.guard_requirement_profile_header();

CREATE OR REPLACE FUNCTION docintel.guard_requirement_profile_item()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    p_tenant varchar(128);
    p_id uuid;
    p_status varchar(20);
BEGIN
    p_tenant := COALESCE(NEW.tenant_id, OLD.tenant_id);
    p_id := COALESCE(NEW.requirement_profile_id, OLD.requirement_profile_id);
    SELECT status INTO p_status
    FROM docintel.document_requirement_profiles
    WHERE tenant_id = p_tenant AND requirement_profile_id = p_id;
    IF p_status IS DISTINCT FROM 'DRAFT' THEN
        RAISE EXCEPTION 'published/retired requirement profile items are immutable';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER requirement_profile_items_guard
BEFORE INSERT OR UPDATE OR DELETE ON docintel.document_requirement_profile_items
FOR EACH ROW EXECUTE FUNCTION docintel.guard_requirement_profile_item();

-- -----------------------------------------------------------------------------
-- RLS: tenant-owned transactional/configuration tables
-- Application must SET LOCAL app.tenant_id = '<authorized tenant>' in each transaction.
-- -----------------------------------------------------------------------------
DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'tenant_settings','actors','registered_devices','retention_policies',
        'document_requirement_profiles','document_requirement_profile_items','subject_requirement_assignments',
        'subjects','subject_identifiers','channel_identities','documents','document_artifacts','document_quality_results','processing_jobs',
        'processing_runs','processor_invocations','document_classifications','extracted_facts',
        'document_field_values','validation_results','human_verifications','entity_links',
        'integration_intake_events','idempotency_records','audit_chain_heads','audit_events'
    ]
    LOOP
        EXECUTE format('ALTER TABLE docintel.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format(
            'CREATE POLICY tenant_isolation ON docintel.%I USING (tenant_id = docintel.current_tenant_id()) WITH CHECK (tenant_id = docintel.current_tenant_id())',
            t
        );
    END LOOP;
END $$;

-- Global/default configuration tables use owner/scope tenant columns rather than tenant_id.
ALTER TABLE docintel.document_types ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_types_read_scope ON docintel.document_types
USING (owner_tenant_id IS NULL OR owner_tenant_id = docintel.current_tenant_id())
WITH CHECK (owner_tenant_id = docintel.current_tenant_id());

ALTER TABLE docintel.canonical_fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY canonical_fields_read_scope ON docintel.canonical_fields
USING (owner_tenant_id IS NULL OR owner_tenant_id = docintel.current_tenant_id())
WITH CHECK (owner_tenant_id = docintel.current_tenant_id());

ALTER TABLE docintel.extraction_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY extraction_profiles_read_scope ON docintel.extraction_profiles
USING (scope_tenant_id IS NULL OR scope_tenant_id = docintel.current_tenant_id())
WITH CHECK (scope_tenant_id = docintel.current_tenant_id());

-- extraction_profile_fields/normalizers/validators are authorized through their parent profile by the service layer.
ALTER TABLE docintel.extraction_profile_fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY extraction_profile_fields_scope ON docintel.extraction_profile_fields
USING (
    EXISTS (
        SELECT 1 FROM docintel.extraction_profiles p
        WHERE p.profile_id = extraction_profile_fields.profile_id
          AND (p.scope_tenant_id IS NULL OR p.scope_tenant_id = docintel.current_tenant_id())
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1 FROM docintel.extraction_profiles p
        WHERE p.profile_id = extraction_profile_fields.profile_id
          AND p.scope_tenant_id = docintel.current_tenant_id()
    )
);

ALTER TABLE docintel.profile_field_normalizers ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_field_normalizers_scope ON docintel.profile_field_normalizers
USING (
    EXISTS (
        SELECT 1
        FROM docintel.extraction_profile_fields f
        JOIN docintel.extraction_profiles p ON p.profile_id = f.profile_id
        WHERE f.profile_field_id = profile_field_normalizers.profile_field_id
          AND (p.scope_tenant_id IS NULL OR p.scope_tenant_id = docintel.current_tenant_id())
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1
        FROM docintel.extraction_profile_fields f
        JOIN docintel.extraction_profiles p ON p.profile_id = f.profile_id
        WHERE f.profile_field_id = profile_field_normalizers.profile_field_id
          AND p.scope_tenant_id = docintel.current_tenant_id()
    )
);

ALTER TABLE docintel.profile_field_validators ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_field_validators_scope ON docintel.profile_field_validators
USING (
    EXISTS (
        SELECT 1
        FROM docintel.extraction_profile_fields f
        JOIN docintel.extraction_profiles p ON p.profile_id = f.profile_id
        WHERE f.profile_field_id = profile_field_validators.profile_field_id
          AND (p.scope_tenant_id IS NULL OR p.scope_tenant_id = docintel.current_tenant_id())
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1
        FROM docintel.extraction_profile_fields f
        JOIN docintel.extraction_profiles p ON p.profile_id = f.profile_id
        WHERE f.profile_field_id = profile_field_validators.profile_field_id
          AND p.scope_tenant_id = docintel.current_tenant_id()
    )
);

-- Global normalization/validation/quality rule catalogs are read-only to normal tenant application roles; write privilege is reserved for platform administration.

COMMIT;
